let filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/employees.csv"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var employees: [(name: String, dept: String, salary: Double)] = []

for line in lines.dropFirst() {
    let fields = line.components(separatedBy: ",")
    if fields.count >= 4 {
        let name = fields[1].trimmingCharacters(in: .whitespaces)
        let dept = fields[2].trimmingCharacters(in: .whitespaces)
        let salaryStr = fields[3].trimmingCharacters(in: .whitespaces)
        let salary = Double(salaryStr) ?? 0
        employees.append((name, dept, salary))
    }
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.dept, default: []].append(emp.salary)
}

let sortedDepts = deptSalaries.keys.sorted()

let highestPaid = employees.max { $0.salary < $1.salary }!

var deptCounts: [String: Int] = [:]
for emp in employees {
    deptCounts[emp.dept, default: 0] += 1
}
let deptsOver2 = deptCounts.filter { $0.value > 2 }.sorted { $0.key < $1.key }

let totalBudget = employees.reduce(0.0) { $0 + $1.salary }

func formatInt(_ number: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.minimumFractionDigits = 0
    formatter.maximumFractionDigits = 0
    return formatter.string(from: NSNumber(value: number)) ?? "0"
}

func formatTwoDecimals(_ number: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.minimumFractionDigits = 2
    formatter.maximumFractionDigits = 2
    return formatter.string(from: NSNumber(value: number)) ?? "0.00"
}

print("=== Salary Report ===")
print("")
print("Average Salary by Department:")
for dept in sortedDepts {
    let salaries = deptSalaries[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): $\(formatTwoDecimals(avg))")
}
print("")
print("Highest Paid: \(highestPaid.name) ($\(formatInt(highestPaid.salary)))")
print("")
print("Departments with >2 employees:")
for (dept, count) in deptsOver2 {
    print("  \(dept) (\(count) employees)")
}
print("")
print("Total Budget: $\(formatInt(totalBudget))")

