import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/employees.csv";

        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String header = br.readLine();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCounts = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        String line;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(",");
            String name = parts[1].trim();
            String department = parts[2].trim();
            String salaryStr = parts[3].trim().replaceAll("[,$]", "");
            double salary = Double.parseDouble(salaryStr);

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCounts.merge(department, 1, Integer::sum);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }
        br.close();

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            List<Double> salaries = entry.getValue();
            double avg = salaries.stream().mapToDouble(Double::doubleValue).average().orElse(0);
            System.out.printf("  %s: $%,.2f%n", entry.getKey(), avg);
        }
        System.out.println();
        System.out.printf("Highest Paid: %s ($%,.0f)%n", highestName, highestSalary);
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (Map.Entry<String, Integer> entry : deptCounts.entrySet()) {
            if (entry.getValue() > 2) {
                System.out.printf("  %s (%d employees)%n", entry.getKey(), entry.getValue());
            }
        }
        System.out.println();
        System.out.printf("Total Budget: $%,.0f%n", totalBudget);
    }
}

