use std::collections::BTreeMap;
use std::fs;

fn format_number_with_commas(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

fn format_average(avg: f64) -> String {
    let cents = (avg * 100.0).round() as i64;
    let int_part = (cents / 100) as u64;
    let dec_part = (cents % 100) as u32;
    let int_str = format_number_with_commas(int_part);
    format!("${}.{:02}", int_str, dec_part)
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/employees.csv";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let lines: Vec<&str> = content.lines().collect();
    let header = lines[0];

    let cols: Vec<&str> = header.split(',').map(|c| c.trim()).collect();
    let name_idx = cols.iter().position(|c| *c == "name").unwrap();
    let dept_idx = cols.iter().position(|c| *c == "department").unwrap();
    let salary_idx = cols.iter().position(|c| *c == "salary").unwrap();

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut total_budget: u64 = 0;
    let mut highest_paid: (String, u64) = (String::new(), 0);

    for line in lines.iter().skip(1) {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let fields: Vec<&str> = trimmed.split(',').map(|f| f.trim()).collect();
        let name = fields[name_idx].to_string();
        let dept = fields[dept_idx].to_string();
        let salary: f64 = fields[salary_idx].parse().unwrap();
        let salary_int = salary as u64;

        dept_salaries.entry(dept).or_insert_with(Vec::new).push(salary);
        total_budget += salary_int;

        if salary_int > highest_paid.1 {
            highest_paid = (name, salary_int);
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: {}", dept, format_average(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_paid.0, format_number_with_commas(highest_paid.1));
    println!();
    println!("Departments with >2 employees:");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }
    println!();
    println!("Total Budget: ${}", format_number_with_commas(total_budget));
}

