const header = lines[0].split(',').map(h => h.trim());
const data: Record<string, string>[] = [];

for (let i = 1; i < lines.length; i++) {
  if (lines[i].trim() === '') continue;
  const cols = lines[i].split(',');
  const row: Record<string, string> = {};
  for (let j = 0; j < header.length; j++) {
    row[header[j]] = (cols[j] || '').trim();
  }
  data.push(row);
}

function formatNumber(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const parts = fixed.split('.');
  let intPart = parts[0];
  const decPart = parts[1];
  const negative = intPart.startsWith('-');
  if (negative) intPart = intPart.substring(1);
  let formatted = '';
  for (let i = intPart.length - 1, count = 0; i >= 0; i--, count++) {
    if (count > 0 && count % 3 === 0) formatted = ',' + formatted;
    formatted = intPart[i] + formatted;
  }
  if (negative) formatted = '-' + formatted;
  return decimals > 0 ? formatted + '.' + decPart : formatted;
}

const deptSalaries: Map<string, number[]> = new Map();
for (const row of data) {
  const dept = row['department'];
  const salary = parseFloat(row['salary']);
  if (!deptSalaries.has(dept)) deptSalaries.set(dept, []);
  deptSalaries.get(dept)!.push(salary);
}

const output: string[] = [];
output.push('=== Salary Report ===');
output.push('');
output.push('Average Salary by Department:');

const sortedDepts = [...deptSalaries.keys()].sort();
for (const dept of sortedDepts) {
  const salaries = deptSalaries.get(dept)!;
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  output.push(`  ${dept}: $${formatNumber(avg, 2)}`);
}

