let highestName = '';
let highestSalary = -Infinity;
for (const row of data) {
  const salary = parseFloat(row['salary']);
  if (salary > highestSalary) {
    highestSalary = salary;
    highestName = row['name'];
  }
}
output.push(`Highest Paid: ${highestName} ($${formatNumber(highestSalary, 0)})`);

output.push('');

output.push('Departments with >2 employees:');
const deptCounts: Map<string, number> = new Map();
for (const row of data) {
  const dept = row['department'];
  deptCounts.set(dept, (deptCounts.get(dept) || 0) + 1);
}
const deptsOver2 = [...deptCounts.entries()].filter(([, count]) => count > 2).sort((a, b) => a[0].localeCompare(b[0]));
for (const [dept, count] of deptsOver2) {
  output.push(`  ${dept} (${count} employees)`);
}

output.push('');

const totalBudget = data.reduce((sum, row) => sum + parseFloat(row['salary']), 0);
output.push(`Total Budget: $${formatNumber(totalBudget, 0)}`);

