import java.io.*;
import java.net.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18924/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream(), "UTF-8"));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        List<String[]> products = new ArrayList<>();

        int i = 0;
        while (i < json.length()) {
            int start = json.indexOf('{', i);
            if (start == -1) break;
            int end = json.indexOf('}', start);
            if (end == -1) break;

            String obj = json.substring(start, end + 1);

            String name = extractString(obj, "name");
            String price = extractNumber(obj, "price");

            if (name != null && price != null) {
                products.add(new String[]{name, price});
            }

            i = end + 1;
        }

        List<String[]> filtered = new ArrayList<>();
        for (String[] p : products) {
            double price = Double.parseDouble(p[1]);
            if (price > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> a[0].compareTo(b[0]));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        double total = 0.0;
        for (String[] p : filtered) {
            double price = Double.parseDouble(p[1]);
            total += price;
            System.out.printf("%s: $%.2f%n", p[0], price);
        }
        System.out.println();
        System.out.printf("Count: %d%n", filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }

    private static String extractString(String obj, String key) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");
        Matcher m = p.matcher(obj);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }

    private static String extractNumber(String obj, String key) {
        Pattern p = Pattern.compile("\"" + Pattern.quote(key) + "\"\\s*:\\s*(-?[\\d]+\\.?[\\d]*)");
        Matcher m = p.matcher(obj);
        if (m.find()) {
            return m.group(1);
        }
        return null;
    }
}

