use std::collections::{BTreeMap, BTreeSet};
use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/app.log";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<String, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("Missing closing bracket");
        let timestamp_part = &line[1..close_bracket];

        // Extract hour (positions 11-12 in "YYYY-MM-DD HH:MM:SS")
        let hour = &timestamp_part[11..13];
        let hour_key = format!("{}:00", hour);
        *hour_counts.entry(hour_key).or_insert(0) += 1;

        // After "] "
        let rest = &line[close_bracket + 2..];

        // LEVEL is before " ("
        let level_end = rest.find(" (").expect("Missing ' (' after level");
        let level = rest[..level_end].to_string();
        *level_counts.entry(level.clone()).or_insert(0) += 1;

        // component is between "(" and ")"
        let comp_start = level_end + 2;
        let comp_end_rel = rest[comp_start..].find(')').expect("Missing ')' for component");
        let comp_end = comp_start + comp_end_rel;
        let component = rest[comp_start..comp_end].to_string();

        // message is after ") - "
        let msg_start = comp_end + 3;
        let message = rest[msg_start..].to_string();

        if level == "ERROR" {
            *error_component_counts.entry(component).or_insert(0) += 1;
            error_messages.insert(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(comp, count)| (comp.clone(), *count))
        .unwrap_or_else(|| ("N/A".to_string(), 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(h, count)| (h.clone(), *count))
        .unwrap_or_else(|| ("00:00".to_string(), 0));
    println!("Busiest Hour: {} ({} entries)", busiest_hour, busiest_count);
}

