import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    static String extractString(String obj, String key) {
        int i = obj.indexOf("\"" + key + "\"");
        int colon = obj.indexOf(':', i);
        int q1 = obj.indexOf('"', colon);
        int q2 = obj.indexOf('"', q1 + 1);
        return obj.substring(q1 + 1, q2);
    }

    static double extractNumber(String obj, String key) {
        int i = obj.indexOf("\"" + key + "\"");
        int colon = obj.indexOf(':', i);
        int j = colon + 1;
        while (j < obj.length() && (obj.charAt(j) == ' ' || obj.charAt(j) == ',')) j++;
        int k = j;
        while (k < obj.length() && (Character.isDigit(obj.charAt(k)) || obj.charAt(k) == '-'
                || obj.charAt(k) == '+' || obj.charAt(k) == '.' || obj.charAt(k) == 'e'
                || obj.charAt(k) == 'E')) k++;
        return Double.parseDouble(obj.substring(j, k).trim());
    }

    static String fmt(double d) {
        if (d == Math.floor(d) && !Double.isInfinite(d)) {
            return Long.toString((long) d);
        }
        return Double.toString(d);
    }

    public static void main(String[] args) throws Exception {
        String path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/graph.json";
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) sb.append(line).append("\n");
        }
        String json = sb.toString();

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        int nodesIdx = json.indexOf("\"nodes\"");
        int nStart = json.indexOf('[', nodesIdx);
        int nEnd = json.indexOf(']', nStart);
        String nodesStr = json.substring(nStart + 1, nEnd);
        Matcher nm = Pattern.compile("\"((?:[^\"\\\\]|\\\\.)*)\"").matcher(nodesStr);
        while (nm.find()) nodes.add(nm.group(1));

        Map<String, Integer> idx = new HashMap<>();
        for (int i = 0; i < nodes.size(); i++) idx.put(nodes.get(i), i);

        // Parse edges (undirected)
        List<List<int[]>> adj = new ArrayList<>();
        List<List<Double>> wAdj = new ArrayList<>();
        for (int i = 0; i < nodes.size(); i++) {
