            String from = extractString(obj, "from");
            String to = extractString(obj, "to");
            double w = extractNumber(obj, "weight");
            int u = idx.get(from);
            int v = idx.get(to);
            adj.get(u).add(new int[]{v});
            wAdj.get(u).add(w);
            adj.get(v).add(new int[]{u});
            wAdj.get(v).add(w);
        }

        // Dijkstra from A
        int n = nodes.size();
        int src = idx.get("A");
        double INF = Double.POSITIVE_INFINITY;
        double[] dist = new double[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        boolean[] done = new boolean[n];
        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
        pq.add(new double[]{0, src});
        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            int u = (int) cur[1];
            if (done[u]) continue;
            done[u] = true;
            List<int[]> ns = adj.get(u);
            List<Double> ws = wAdj.get(u);
            for (int i = 0; i < ns.size(); i++) {
                int v = ns.get(i)[0];
                double nd = dist[u] + ws.get(i);
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.add(new double[]{nd, v});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        for (String name : sorted) {
            double d = dist[idx.get(name)];
            if (Double.isInfinite(d)) {
                System.out.println("A -> " + name + ": unreachable");
            } else {
                System.out.println("A -> " + name + ": " + fmt(d));
            }
        }
    }
}

