function walkDir(dir: string, root: string, visited: Set<string>): Map<string, FileEntry[]> {
  const result = new Map<string, FileEntry[]>();

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return result;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      const subResult = walkDir(fullPath, root, visited);
      for (const [ext, files] of subResult) {
        if (!result.has(ext)) result.set(ext, []);
        result.get(ext)!.push(...files);
      }
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      let buffer: Buffer;
      try {
        buffer = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const lines = countLines(buffer);
      const chars = buffer.length;
      const ext = getExtension(entry.name);

      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }

  return result;
}

const visited = new Set<string>();
visited.add(fs.realpathSync(rootDir));
const grouped = walkDir(rootDir, rootDir, visited);

const sortedExts = Array.from(grouped.keys()).sort();

for (const ext of sortedExts) {
  grouped.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
}

const out: string[] = [];
