out.push('');

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of sortedExts) {
  const files = grouped.get(ext)!;
  const extLines = files.reduce((s, f) => s + f.lines, 0);
  const extChars = files.reduce((s, f) => s + f.chars, 0);

  out.push(`Extension: ${ext}`);
  out.push(`  Files: ${files.length}`);
