enum Value {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser {
            input: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();
        if self.pos >= self.input.len() {
            return Value::Null;
        }
        match self.input[self.pos] {
            b'"' => Value::String(self.parse_string()),
            b'[' => Value::Array(self.parse_array()),
            b'{' => Value::Object(self.parse_object()),
            b't' => {
                self.pos += 4;
                Value::Bool(true)
            }
            b'f' => {
                self.pos += 5;
                Value::Bool(false)
            }
            b'n' => {
                self.pos += 4;
                Value::Null
            }
            _ => Value::Number(self.parse_number()),
        }
    }

    fn parse_string(&mut self) -> String {
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'"' {
            self.pos += 1;
        }
        let mut bytes = Vec::new();
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == b'"' {
                self.pos += 1;
                break;
            } else if c == b'\\' {
                self.pos += 1;
                if self.pos < self.input.len() {
                    match self.input[self.pos] {
                        b'"' => bytes.push(b'"'),
                        b'\\' => bytes.push(b'\\'),
                        b'/' => bytes.push(b'/'),
                        b'n' => bytes.push(b'\n'),
                        b't' => bytes.push(b'\t'),
                        b'r' => bytes.push(b'\r'),
                        b'b' => bytes.push(0x08),
                        b'f' => bytes.push(0x0C),
                        b'u' => {
                            if self.pos + 4 < self.input.len() {
                                let hex =
                                    std::str::from_utf8(&self.input[self.pos + 1..self.pos + 5])
                                        .unwrap_or("0000");
                                let code = u32::from_str_radix(hex, 16).unwrap_or(0);
                                if let Some(ch) = char::from_u32(code) {
                                    let mut buf = [0u8; 4];
                                    bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                                }
                                self.pos += 4;
                            }
                        }
                        _ => {}
                    }
                }
                self.pos += 1;
            } else {
                bytes.push(c);
                self.pos += 1;
            }
        }
        String::from_utf8_lossy(&bytes).into_owned()
    }

    fn parse_number(&mut self) -> f64 {
        self.skip_ws();
        let start = self.pos;
        if self.pos < self.input.len() && self.input[self.pos] == b'-' {
            self.pos += 1;
        }
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-'
            {
