            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("0");
        s.parse::<f64>().unwrap_or(0.0)
    }

    fn parse_array(&mut self) -> Vec<Value> {
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'[' {
            self.pos += 1;
        }
        let mut arr = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return arr;
        }
        loop {
            let val = self.parse_value();
            arr.push(val);
            self.skip_ws();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
        }
        arr
    }

    fn parse_object(&mut self) -> Vec<(String, Value)> {
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'{' {
            self.pos += 1;
        }
        let mut obj = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
