                .and_then(|(_, v)| {
                    if let Value::String(s) = v {
                        Some(s.clone())
                    } else {
                        None
                    }
                })
                .unwrap_or_default();
            let price = fields
                .iter()
                .find(|(k, _)| k == "price")
                .and_then(|(_, v)| {
                    if let Value::Number(n) = v {
                        Some(*n)
                    } else {
                        None
                    }
                })
                .unwrap_or(0.0);
            products.push((name, price));
        }
    }
    products
}

