function multiply(M: number[][], N: number[][]): number[][] {
    const rows = M.length;
    const cols = N[0].length;
    const inner = N.length;
    const C: number[][] = Array.from({ length: rows }, () => Array(cols).fill(0));
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            for (let k = 0; k < inner; k++) {
                C[i][j] += M[i][k] * N[k][j];
            }
        }
    }
    return C;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
    let det = 0;
    for (let j = 0; j < n; j++) {
        const minor: number[][] = [];
        for (let i = 1; i < n; i++) {
            const row: number[] = [];
            for (let k = 0; k < n; k++) {
                if (k !== j) row.push(M[i][k]);
            }
            minor.push(row);
        }
        det += ((j % 2 === 0) ? 1 : -1) * M[0][j] * determinant(minor);
    }
    return det;
}

