func multiply(_ M: [[Int]], _ N: [[Int]]) -> [[Int]] {
    let rows = M.count
    let cols = N[0].count
    var result = [[Int]](repeating: [Int](repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            var sum = 0
            for k in 0..<M[0].count {
                sum += M[i][k] * N[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 { return M[0][0] }
    if n == 2 { return M[0][0]*M[1][1] - M[0][1]*M[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n where k != j {
                row.append(M[i][k])
            }
            minor.append(row)
        }
        let sign = (j % 2 == 0) ? 1 : -1
        det += sign * M[0][j] * determinant(minor)
    }
    return det
}

