#define BASE_DIR "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/project_tree"

typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileEntry;

typedef struct {
    FileEntry *entries;
    int count;
    int capacity;
} FileList;

static void add_entry(FileList *list, const char *relpath, const char *ext, long lines, long chars) {
    if (list->count >= list->capacity) {
        int newcap = list->capacity ? list->capacity * 2 : 64;
        list->entries = (FileEntry *)realloc(list->entries, (size_t)newcap * sizeof(FileEntry));
        if (!list->entries) { fprintf(stderr, "realloc failed\n"); exit(1); }
        list->capacity = newcap;
    }
    list->entries[list->count].relpath = strdup(relpath);
    list->entries[list->count].ext = strdup(ext);
    list->entries[list->count].lines = lines;
    list->entries[list->count].chars = chars;
    list->count++;
}

static void get_ext(const char *filename, char *ext, size_t ext_size) {
    const char *dot = strrchr(filename, '.');
    if (dot && dot != filename) {
        size_t len = strlen(dot);
        if (len >= ext_size) len = ext_size - 1;
        memcpy(ext, dot, len);
        ext[len] = '\0';
    } else {
        ext[0] = '\0';
    }
}

static void count_file(const char *path, long *lines, long *chars) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        *lines = 0;
        *chars = 0;
        return;
    }
    long line_count = 0;
    long char_count = 0;
    int ended_with_newline = 0;
    int has_content = 0;
    int c;
    while ((c = fgetc(f)) != EOF) {
        char_count++;
        has_content = 1;
        if (c == '\n') {
            line_count++;
            ended_with_newline = 1;
        } else {
            ended_with_newline = 0;
        }
    }
    if (has_content && !ended_with_newline) {
        line_count++;
    }
    fclose(f);
    *lines = line_count;
    *chars = char_count;
}

static void walk_dir(const char *full_path, const char *rel_prefix, FileList *list) {
    DIR *d = opendir(full_path);
    if (!d) return;

    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full[4096];
        snprintf(full, sizeof(full), "%s/%s", full_path, entry->d_name);

        struct stat st;
        if (lstat(full, &st) != 0)
            continue;

        if (S_ISLNK(st.st_mode))
            continue;

        if (S_ISREG(st.st_mode)) {
            char rel[4096];
            if (rel_prefix[0] == '\0') {
                snprintf(rel, sizeof(rel), "%s", entry->d_name);
            } else {
                snprintf(rel, sizeof(rel), "%s/%s", rel_prefix, entry->d_name);
            }

            char ext[256];
            get_ext(entry->d_name, ext, sizeof(ext));

            long lines, chars;
            count_file(full, &lines, &chars);

            add_entry(list, rel, ext, lines, chars);
        } else if (S_ISDIR(st.st_mode)) {
            char rel_prefix_new[4096];
            if (rel_prefix[0] == '\0') {
                snprintf(rel_prefix_new, sizeof(rel_prefix_new), "%s", entry->d_name);
            } else {
                snprintf(rel_prefix_new, sizeof(rel_prefix_new), "%s/%s", rel_prefix, entry->d_name);
            }
            walk_dir(full, rel_prefix_new, list);
        }
    }
    closedir(d);
}

static int compare_entries(const void *a, const void *b) {
    const FileEntry *ea = (const FileEntry *)a;
    const FileEntry *eb = (const FileEntry *)b;
    int cmp = strcmp(ea->ext, eb->ext);
    if (cmp != 0) return cmp;
    return strcmp(ea->relpath, eb->relpath);
}

