        vec![3, 2, 1],
    ];

    let c = mat_mul(&a, &b);
    let det = determinant(&c);

    println!("=== Matrix Operations ===");
    println!();
    println!("Matrix A:");
    print_matrix(&a);
    println!();
    println!("Matrix B:");
    print_matrix(&b);
    println!();
    println!("A x B =");
    print_matrix(&c);
    println!();
    println!("Determinant: {}", det);
