fn mat_mul(a: &Vec<Vec<i64>>, b: &Vec<Vec<i64>>) -> Vec<Vec<i64>> {
    let n = a.len();
    let mut c = vec![vec![0i64; n]; n];
    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    c
}

fn determinant(m: &Vec<Vec<i64>>) -> i64 {
    let n = m.len();
    if n == 1 {
        return m[0][0];
    }
    if n == 2 {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    }
    let mut det = 0i64;
    for j in 0..n {
        let mut minor = vec![vec![0i64; n - 1]; n - 1];
        for i in 1..n {
            let mut col = 0;
            for k in 0..n {
                if k == j {
                    continue;
                }
                minor[i - 1][col] = m[i][k];
                col += 1;
            }
        }
        let sign = if j % 2 == 0 { 1 } else { -1 };
        det += sign * m[0][j] * determinant(&minor);
    }
    det
}

fn print_matrix(m: &Vec<Vec<i64>>) {
    for row in m {
        let parts: Vec<String> = row.iter().map(|v| format!("{:4}", v)).collect();
        println!("  {}", parts.join(" "));
    }
}

