use std::fs;
use std::collections::HashMap;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some('f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some('n') => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.next();
        let mut entries = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(entries);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next();
            let val = self.parse_value();
            entries.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected , or } in object"),
            }
        }
        Json::Object(entries)
    }

    fn parse_array(&mut self) -> Json {
        self.next();
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(items);
        }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected , or ] in array"),
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.next();
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => match self.next() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('n') => s.push('\n'),
                    Some('t') => s.push('\t'),
                    Some('r') => s.push('\r'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some(c) => panic!("Unknown escape: {}", c),
                },
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            if c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || c.is_ascii_digit() {
                s.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        Json::Number(s.parse::<f64>().unwrap())
    }
}

fn get_obj_field(obj: &Json, key: &str) -> &Json {
    if let Json::Object(entries) = obj {
        for (k, v) in entries {
            if k == key {
                return v;
            }
        }
    }
    panic!("Key '{}' not found", key);
}

fn main() {
    let content = fs::read_to_string(
        "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/graph.json",
    )
    .expect("Failed to read graph.json");

    let mut parser = Parser::new(&content);
    let json = parser.parse_value();

    let nodes_json = get_obj_field(&json, "nodes");
    let edges_json = get_obj_field(&json, "edges");

    let nodes: Vec<String> = if let Json::Array(arr) = nodes_json {
        arr.iter()
            .map(|v| {
                if let Json::String(s) = v {
                    s.clone()
                } else {
                    panic!("Expected string in nodes")
                }
            })
            .collect()
    } else {
        panic!("Expected array for nodes")
    };

    let mut adj: HashMap<String, Vec<(String, i64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }

    if let Json::Array(edges) = edges_json {
        for edge in edges {
            let from = get_obj_field(edge, "from");
            let to = get_obj_field(edge, "to");
            let weight = get_obj_field(edge, "weight");

            let from = if let Json::String(s) = from {
                s.clone()
            } else {
                panic!("Expected string for from")
            };
            let to = if let Json::String(s) = to {
                s.clone()
            } else {
                panic!("Expected string for to")
            };
