    if (p->pos < p->len && p->buf[p->pos] == '-') p->pos++;
    while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    if (p->pos < p->len && p->buf[p->pos] == '.') {
        p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    if (p->pos < p->len && (p->buf[p->pos] == 'e' || p->buf[p->pos] == 'E')) {
        p->pos++;
        if (p->pos < p->len && (p->buf[p->pos] == '+' || p->buf[p->pos] == '-')) p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    char *tmp = (char *)malloc(p->pos - start + 1);
    memcpy(tmp, p->buf + start, p->pos - start);
    tmp[p->pos - start] = '\0';
    double d = strtod(tmp, NULL);
    free(tmp);
    return json_new_number(d);
}

static json_value *parse_array(parser *p) {
    p->pos++; /* skip [ */
    json_value *arr = json_new_array();
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == ']') {
        p->pos++;
        return arr;
    }
    while (1) {
        skip_ws(p);
        json_value *item = parse_value(p);
        json_array_append(arr, item);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static json_value *parse_object(parser *p) {
    p->pos++; /* skip { */
    json_value *obj = json_new_object();
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') {
        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ':') p->pos++;
        skip_ws(p);
        json_value *val = parse_value(p);
        json_object_set(obj, key, val);
        free(key);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new_null();
    char c = p->buf[p->pos];
    if (c == '"') return parse_string(p);
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == 't') { p->pos += 4; return json_new_bool(1); }
    if (c == 'f') { p->pos += 5; return json_new_bool(0); }
    if (c == 'n') { p->pos += 4; return json_new_null(); }
    return parse_number(p);
}

/* Deep equality for JSON values */
static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->number_val == b->number_val;
        case JSON_STRING: return strcmp(a->string_val, b->string_val) == 0;
        case JSON_ARRAY: {
            if (a->array.count != b->array.count) return 0;
            for (size_t i = 0; i < a->array.count; i++)
                if (!json_equal(a->array.items[i], b->array.items[i])) return 0;
            return 1;
        }
        case JSON_OBJECT: {
            if (a->object.count != b->object.count) return 0;
            for (size_t i = 0; i < a->object.count; i++) {
                const char *k = a->object.members[i].key;
                int found = 0;
                for (size_t j = 0; j < b->object.count; j++) {
                    if (strcmp(k, b->object.members[j].key) == 0) {
                        if (!json_equal(a->object.members[i].value, b->object.members[j].value)) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

/* Merge logic */
static json_value *deep_merge(const json_value *a, const json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new_object();
        /* Add all keys from A */
        for (size_t i = 0; i < a->object.count; i++) {
            const char *key = a->object.members[i].key;
            json_value *aval = a->object.members[i].value;
            /* Check if B has this key */
            int found = 0;
            for (size_t j = 0; j < b->object.count; j++) {
                if (strcmp(key, b->object.members[j].key) == 0) {
                    json_value *merged = deep_merge(aval, b->object.members[j].value);
                    json_object_set(result, key, merged);
                    found = 1;
                    break;
                }
            }
            if (!found) {
                /* Key only in A - include as-is (deep copy) */
                json_value *copy;
                if (aval->type == JSON_OBJECT || aval->type == JSON_ARRAY) {
                    /* We need a deep copy; simplest: re-serialize and re-parse */
                    /* Actually let's just do a recursive copy */
                    copy = deep_copy(aval);
                } else {
                    copy = deep_copy(aval);
                }
                json_object_set(result, key, copy);
            }
        }
        /* Add keys only in B */
        for (size_t j = 0; j < b->object.count; j++) {
            const char *key = b->object.members[j].key;
            int found = 0;
            for (size_t i = 0; i < a->object.count; i++) {
                if (strcmp(key, a->object.members[i].key) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                json_value *copy = deep_copy(b->object.members[j].value);
                json_object_set(result, key, copy);
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new_array();
        /* Add all items from A */
        for (size_t i = 0; i < a->array.count; i++) {
            json_array_append(result, deep_copy(a->array.items[i]));
        }
        /* Add items from B that are not already in result */
        for (size_t j = 0; j < b->array.count; j++) {
            int dup = 0;
            for (size_t i = 0; i < result->array.count; i++) {
                if (json_equal(result->array.items[i], b->array.items[j])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                json_array_append(result, deep_copy(b->array.items[j]));
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return deep_copy(b);
}

static json_value *deep_copy(const json_value *v) {
    switch (v->type) {
        case JSON_NULL: return json_new_null();
        case JSON_BOOL: return json_new_bool(v->bool_val);
        case JSON_NUMBER: return json_new_number(v->number_val);
        case JSON_STRING: return json_new_string(v->string_val);
        case JSON_ARRAY: {
            json_value *arr = json_new_array();
            for (size_t i = 0; i < v->array.count; i++)
                json_array_append(arr, deep_copy(v->array.items[i]));
            return arr;
        }
        case JSON_OBJECT: {
            json_value *obj = json_new_object();
            for (size_t i = 0; i < v->object.count; i++)
                json_object_set(obj, v->object.members[i].key, deep_copy(v->object.members[i].value));
            return obj;
        }
    }
    return json_new_null();
}

