/* Serializer */
static void print_string_escaped(FILE *f, const char *s) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20)
                    fprintf(f, "\\u%04x", c);
                else
                    fputc(c, f);
                break;
        }
    }
    fputc('"', f);
}

static void print_number(FILE *f, double d) {
    if (d == (double)(long long)d && fabs(d) < 1e15) {
        fprintf(f, "%lld", (long long)d);
    } else {
        /* Try to find a reasonable representation */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.17g", d);
        /* Remove trailing zeros if it looks like a float */
        /* Actually just use %g with enough precision */
        fprintf(f, "%.17g", d);
    }
}

static void print_value(FILE *f, const json_value *v, int indent, int depth) {
    int i;
    char pad[256];
    for (i = 0; i < indent * depth; i++) pad[i] = ' ';
    pad[i] = '\0';
    char pad_inner[256];
    for (i = 0; i < indent * (depth + 1); i++) pad_inner[i] = ' ';
    pad_inner[i] = '\0';

    switch (v->type) {
        case JSON_NULL:
            fprintf(f, "null");
            break;
        case JSON_BOOL:
            fprintf(f, "%s", v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(f, v->number_val);
            break;
        case JSON_STRING:
            print_string_escaped(f, v->string_val);
            break;
        case JSON_ARRAY:
            if (v->array.count == 0) {
                fprintf(f, "[]");
            } else {
                fprintf(f, "[\n");
                for (size_t j = 0; j < v->array.count; j++) {
                    fprintf(f, "%s", pad_inner);
                    print_value(f, v->array.items[j], indent, depth + 1);
                    if (j + 1 < v->array.count) fputc(',', f);
                    fputc('\n', f);
                }
                fprintf(f, "%s]", pad);
            }
            break;
        case JSON_OBJECT:
            if (v->object.count == 0) {
                fprintf(f, "{}");
            } else {
                /* Sort keys alphabetically */
                json_member *sorted = (json_member *)malloc(v->object.count * sizeof(json_member));
                for (size_t j = 0; j < v->object.count; j++) {
                    sorted[j].key = v->object.members[j].key;
                    sorted[j].value = v->object.members[j].value;
                }
                /* Simple insertion sort */
                for (size_t j = 1; j < v->object.count; j++) {
                    json_member tmp = sorted[j];
                    size_t k = j;
                    while (k > 0 && strcmp(sorted[k-1].key, tmp.key) > 0) {
                        sorted[k] = sorted[k-1];
                        k--;
                    }
                    sorted[k] = tmp;
                }
                fprintf(f, "{\n");
                for (size_t j = 0; j < v->object.count; j++) {
                    fprintf(f, "%s", pad_inner);
                    print_string_escaped(f, sorted[j].key);
                    fprintf(f, ": ");
                    print_value(f, sorted[j].value, indent, depth + 1);
                    if (j + 1 < v->object.count) fputc(',', f);
                    fputc('\n', f);
                }
                fprintf(f, "%s}", pad);
                free(sorted);
            }
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    *out_len = rd;
    fclose(f);
    return buf;
}

