#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value json_value;

typedef struct {
    char *key;
    json_value *value;
} json_member;

struct json_value {
    json_type type;
    union {
        int bool_val;
        double number_val;
        char *string_val;
        struct {
            json_value **items;
            size_t count;
            size_t cap;
        } array;
        struct {
            json_member *members;
            size_t count;
            size_t cap;
        } object;
    };
};

static json_value *json_new_null(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_NULL;
    return v;
}

static json_value *json_new_bool(int b) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_BOOL;
    v->bool_val = b;
    return v;
}

static json_value *json_new_number(double d) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_NUMBER;
    v->number_val = d;
    return v;
}

static json_value *json_new_string(const char *s) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_STRING;
    v->string_val = strdup(s);
    return v;
}

static json_value *json_new_array(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_ARRAY;
    return v;
}

static json_value *json_new_object(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_OBJECT;
    return v;
}

static void json_array_append(json_value *arr, json_value *item) {
    if (arr->array.count >= arr->array.cap) {
        arr->array.cap = arr->array.cap ? arr->array.cap * 2 : 4;
        arr->array.items = (json_value **)realloc(arr->array.items, arr->array.cap * sizeof(json_value *));
    }
    arr->array.items[arr->array.count++] = item;
}

static void json_object_set(json_value *obj, const char *key, json_value *val) {
    if (obj->object.count >= obj->object.cap) {
        obj->object.cap = obj->object.cap ? obj->object.cap * 2 : 4;
        obj->object.members = (json_member *)realloc(obj->object.members, obj->object.cap * sizeof(json_member));
    }
    obj->object.members[obj->object.count].key = strdup(key);
    obj->object.members[obj->object.count].value = val;
    obj->object.count++;
}

static void json_free(json_value *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING:
            free(v->string_val);
            break;
        case JSON_ARRAY:
            for (size_t i = 0; i < v->array.count; i++)
                json_free(v->array.items[i]);
            free(v->array.items);
            break;
        case JSON_OBJECT:
            for (size_t i = 0; i < v->object.count; i++) {
                free(v->object.members[i].key);
                json_free(v->object.members[i].value);
            }
            free(v->object.members);
            break;
        default:
            break;
    }
    free(v);
}

static json_value *deep_copy(const json_value *v);
static json_value *deep_merge(const json_value *a, const json_value *b);

static json_value *deep_copy(const json_value *v) {
    switch (v->type) {
        case JSON_NULL: return json_new_null();
        case JSON_BOOL: return json_new_bool(v->bool_val);
        case JSON_NUMBER: return json_new_number(v->number_val);
        case JSON_STRING: return json_new_string(v->string_val);
        case JSON_ARRAY: {
            json_value *arr = json_new_array();
            for (size_t i = 0; i < v->array.count; i++)
                json_array_append(arr, deep_copy(v->array.items[i]));
            return arr;
        }
        case JSON_OBJECT: {
            json_value *obj = json_new_object();
            for (size_t i = 0; i < v->object.count; i++)
                json_object_set(obj, v->object.members[i].key, deep_copy(v->object.members[i].value));
            return obj;
        }
    }
    return json_new_null();
}

static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->number_val == b->number_val;
        case JSON_STRING: return strcmp(a->string_val, b->string_val) == 0;
        case JSON_ARRAY: {
            if (a->array.count != b->array.count) return 0;
            for (size_t i = 0; i < a->array.count; i++)
                if (!json_equal(a->array.items[i], b->array.items[i])) return 0;
            return 1;
        }
        case JSON_OBJECT: {
            if (a->object.count != b->object.count) return 0;
            for (size_t i = 0; i < a->object.count; i++) {
                const char *k = a->object.members[i].key;
                int found = 0;
                for (size_t j = 0; j < b->object.count; j++) {
                    if (strcmp(k, b->object.members[j].key) == 0) {
                        if (!json_equal(a->object.members[i].value, b->object.members[j].value)) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

static json_value *deep_merge(const json_value *a, const json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new_object();
        for (size_t i = 0; i < a->object.count; i++) {
            const char *key = a->object.members[i].key;
            json_value *aval = a->object.members[i].value;
            int found = 0;
            for (size_t j = 0; j < b->object.count; j++) {
                if (strcmp(key, b->object.members[j].key) == 0) {
                    json_value *merged = deep_merge(aval, b->object.members[j].value);
                    json_object_set(result, key, merged);
                    found = 1;
                    break;
                }
            }
            if (!found) {
                json_object_set(result, key, deep_copy(aval));
            }
        }
        for (size_t j = 0; j < b->object.count; j++) {
            const char *key = b->object.members[j].key;
            int found = 0;
            for (size_t i = 0; i < a->object.count; i++) {
                if (strcmp(key, a->object.members[i].key) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                json_object_set(result, key, deep_copy(b->object.members[j].value));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new_array();
        for (size_t i = 0; i < a->array.count; i++) {
            json_array_append(result, deep_copy(a->array.items[i]));
        }
        for (size_t j = 0; j < b->array.count; j++) {
            int dup = 0;
            for (size_t i = 0; i < result->array.count; i++) {
                if (json_equal(result->array.items[i], b->array.items[j])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                json_array_append(result, deep_copy(b->array.items[j]));
            }
        }
        return result;
    }
    return deep_copy(b);
}

/* Parser */
typedef struct {
    const char *buf;
    size_t pos;
    size_t len;
} parser;

static void skip_ws(parser *p) {
    while (p->pos < p->len) {
        char c = p->buf[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r')
            p->pos++;
        else
            break;
    }
}

static json_value *parse_value(parser *p);

static char *parse_string_raw(parser *p) {
    p->pos++;
    size_t cap = 64;
    char *out = (char *)malloc(cap);
    size_t len = 0;
    while (p->pos < p->len) {
        char c = p->buf[p->pos];
        if (c == '"') {
            p->pos++;
            out[len] = '\0';
            return out;
        } else if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char esc = p->buf[p->pos];
            char ch;
            switch (esc) {
                case '"': ch = '"'; break;
                case '\\': ch = '\\'; break;
                case '/': ch = '/'; break;
                case 'b': ch = '\b'; break;
                case 'f': ch = '\f'; break;
                case 'n': ch = '\n'; break;
                case 'r': ch = '\r'; break;
                case 't': ch = '\t'; break;
                case 'u': {
                    unsigned int code = 0;
                    for (int i = 0; i < 4; i++) {
                        p->pos++;
                        if (p->pos >= p->len) break;
                        char h = p->buf[p->pos];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (unsigned)(h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (unsigned)(h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (unsigned)(h - 'A' + 10);
                    }
                    if (code < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; out = realloc(out, cap); }
                        out[len++] = (char)code;
                    } else if (code < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; out = realloc(out, cap); }
                        out[len++] = (char)(0xC0 | (code >> 6));
                        out[len++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; out = realloc(out, cap); }
                        out[len++] = (char)(0xE0 | (code >> 12));
                        out[len++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        out[len++] = (char)(0x80 | (code & 0x3F));
                    }
                    p->pos++;
                    continue;
                }
                default: ch = esc; break;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; out = realloc(out, cap); }
            out[len++] = ch;
        } else {
