static int json_equal(const json_value *a, const json_value *b);

static json_value *deep_copy(const json_value *v) {
    switch (v->type) {
        case JSON_NULL: return json_new_null();
        case JSON_BOOL: return json_new_bool(v->bool_val);
        case JSON_NUMBER: return json_new_number(v->number_val);
        case JSON_STRING: return json_new_string(v->string_val);
        case JSON_ARRAY: {
            json_value *arr = json_new_array();
            for (size_t i = 0; i < v->array.count; i++)
                json_array_append(arr, deep_copy(v->array.items[i]));
            return arr;
        }
        case JSON_OBJECT: {
            json_value *obj = json_new_object();
            for (size_t i = 0; i < v->object.count; i++)
                json_object_set(obj, v->object.members[i].key, deep_copy(v->object.members[i].value));
            return obj;
        }
    }
    return json_new_null();
}

static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->number_val == b->number_val;
        case JSON_STRING: return strcmp(a->string_val, b->string_val) == 0;
        case JSON_ARRAY: {
            if (a->array.count != b->array.count) return 0;
            for (size_t i = 0; i < a->array.count; i++)
                if (!json_equal(a->array.items[i], b->array.items[i])) return 0;
            return 1;
        }
        case JSON_OBJECT: {
            if (a->object.count != b->object.count) return 0;
            for (size_t i = 0; i < a->object.count; i++) {
                const char *k = a->object.members[i].key;
                int found = 0;
                for (size_t j = 0; j < b->object.count; j++) {
                    if (strcmp(k, b->object.members[j].key) == 0) {
                        if (!json_equal(a->object.members[i].value, b->object.members[j].value)) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

static json_value *deep_merge(const json_value *a, const json_value *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new_object();
        for (size_t i = 0; i < a->object.count; i++) {
            const char *key = a->object.members[i].key;
            json_value *aval = a->object.members[i].value;
            int found = 0;
            for (size_t j = 0; j < b->object.count; j++) {
                if (strcmp(key, b->object.members[j].key) == 0) {
                    json_value *merged = deep_merge(aval, b->object.members[j].value);
                    json_object_set(result, key, merged);
                    found = 1;
                    break;
                }
            }
            if (!found) {
                json_object_set(result, key, deep_copy(aval));
            }
        }
        for (size_t j = 0; j < b->object.count; j++) {
            const char *key = b->object.members[j].key;
            int found = 0;
            for (size_t i = 0; i < a->object.count; i++) {
                if (strcmp(key, a->object.members[i].key) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                json_object_set(result, key, deep_copy(b->object.members[j].value));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new_array();
        for (size_t i = 0; i < a->array.count; i++) {
            json_array_append(result, deep_copy(a->array.items[i]));
        }
        for (size_t j = 0; j < b->array.count; j++) {
            int dup = 0;
            for (size_t i = 0; i < result->array.count; i++) {
                if (json_equal(result->array.items[i], b->array.items[j])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                json_array_append(result, deep_copy(b->array.items[j]));
            }
        }
        return result;
    }
    return deep_copy(b);
}

/* Parser */
typedef struct {
    const char *buf;
    size_t pos;
    size_t len;
} parser;

static void skip_ws(parser *p) {
    while (p->pos < p->len) {
        char c = p->buf[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r')
            p->pos++;
        else
            break;
    }
}

static json_value *parse_value(parser *p);

static char *parse_string_raw(parser *p) {
    p->pos++;
    size_t cap = 64;
    char *out = (char *)malloc(cap);
    size_t len = 0;
    while (p->pos < p->len) {
        char c = p->buf[p->pos];
        if (c == '"') {
            p->pos++;
            out[len] = '\0';
            return out;
        } else if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char esc = p->buf[p->pos];
            char ch;
            switch (esc) {
                case '"': ch = '"'; break;
                case '\\': ch = '\\'; break;
                case '/': ch = '/'; break;
                case 'b': ch = '\b'; break;
                case 'f': ch = '\f'; break;
                case 'n': ch = '\n'; break;
                case 'r': ch = '\r'; break;
                case 't': ch = '\t'; break;
                case 'u': {
                    unsigned int code = 0;
                    for (int i = 0; i < 4; i++) {
                        p->pos++;
                        if (p->pos >= p->len) break;
                        char h = p->buf[p->pos];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (unsigned)(h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (unsigned)(h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (unsigned)(h - 'A' + 10);
                    }
                    if (code < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; out = realloc(out, cap); }
                        out[len++] = (char)code;
                    } else if (code < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; out = realloc(out, cap); }
                        out[len++] = (char)(0xC0 | (code >> 6));
                        out[len++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; out = realloc(out, cap); }
                        out[len++] = (char)(0xE0 | (code >> 12));
                        out[len++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        out[len++] = (char)(0x80 | (code & 0x3F));
                    }
                    p->pos++;
                    continue;
                }
                default: ch = esc; break;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; out = realloc(out, cap); }
            out[len++] = ch;
        } else {
            if (len + 1 >= cap) { cap *= 2; out = realloc(out, cap); }
            out[len++] = c;
            p->pos++;
        }
    }
    out[len] = '\0';
    return out;
}

static json_value *parse_number(parser *p) {
    size_t start = p->pos;
    if (p->pos < p->len && p->buf[p->pos] == '-') p->pos++;
    while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    if (p->pos < p->len && p->buf[p->pos] == '.') {
        p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    if (p->pos < p->len && (p->buf[p->pos] == 'e' || p->buf[p->pos] == 'E')) {
        p->pos++;
        if (p->pos < p->len && (p->buf[p->pos] == '+' || p->buf[p->pos] == '-')) p->pos++;
        while (p->pos < p->len && isdigit((unsigned char)p->buf[p->pos])) p->pos++;
    }
    char *tmp = (char *)malloc(p->pos - start + 1);
    memcpy(tmp, p->buf + start, p->pos - start);
    tmp[p->pos - start] = '\0';
    double d = strtod(tmp, NULL);
    free(tmp);
    return json_new_number(d);
}

static json_value *parse_array(parser *p) {
    p->pos++;
    json_value *arr = json_new_array();
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == ']') {
        p->pos++;
        return arr;
    }
    while (1) {
        skip_ws(p);
        json_value *item = parse_value(p);
        json_array_append(arr, item);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == ']') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return arr;
}

static json_value *parse_object(parser *p) {
    p->pos++;
    json_value *obj = json_new_object();
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') {
        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ':') p->pos++;
        skip_ws(p);
        json_value *val = parse_value(p);
        json_object_set(obj, key, val);
        free(key);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->buf[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            break;
        }
    }
    return obj;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new_null();
    char c = p->buf[p->pos];
    if (c == '"') {
        char *s = parse_string_raw(p);
        json_value *v = json_new_string(s);
        free(s);
        return v;
    }
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == 't') { p->pos += 4; return json_new_bool(1); }
    if (c == 'f') { p->pos += 5; return json_new_bool(0); }
    if (c == 'n') { p->pos += 4; return json_new_null(); }
    return parse_number(p);
}

/* Serializer */
static void print_string_escaped(FILE *f, const char *s) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20)
                    fprintf(f, "\\u%04x", (unsigned int)c);
                else
                    fputc((int)c, f);
                break;
        }
    }
    fputc('"', f);
}

static void print_number(FILE *f, double d) {
    if (d == (double)(long long)d && fabs(d) < 1e15) {
        fprintf(f, "%lld", (long long)d);
    } else {
        fprintf(f, "%.17g", d);
    }
}

static void print_value(FILE *f, const json_value *v, int indent, int depth) {
    int i;
    char pad[512];
    char pad_inner[512];
    for (i = 0; i < indent * depth && i < 511; i++) pad[i] = ' ';
    pad[i] = '\0';
    for (i = 0; i < indent * (depth + 1) && i < 511; i++) pad_inner[i] = ' ';
    pad_inner[i] = '\0';

    switch (v->type) {
        case JSON_NULL:
            fprintf(f, "null");
            break;
        case JSON_BOOL:
            fprintf(f, "%s", v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(f, v->number_val);
            break;
        case JSON_STRING:
            print_string_escaped(f, v->string_val);
            break;
        case JSON_ARRAY:
            if (v->array.count == 0) {
                fprintf(f, "[]");
            } else {
                fprintf(f, "[\n");
                for (size_t j = 0; j < v->array.count; j++) {
                    fprintf(f, "%s", pad_inner);
                    print_value(f, v->array.items[j], indent, depth + 1);
                    if (j + 1 < v->array.count) fputc(',', f);
                    fputc('\n', f);
                }
                fprintf(f, "%s]", pad);
            }
            break;
        case JSON_OBJECT:
            if (v->object.count == 0) {
                fprintf(f, "{}");
            } else {
                json_member *sorted = (json_member *)malloc(v->object.count * sizeof(json_member));
                for (size_t j = 0; j < v->object.count; j++) {
                    sorted[j].key = v->object.members[j].key;
                    sorted[j].value = v->object.members[j].value;
                }
                for (size_t j = 1; j < v->object.count; j++) {
                    json_member tmp = sorted[j];
                    size_t k = j;
                    while (k > 0 && strcmp(sorted[k-1].key, tmp.key) > 0) {
                        sorted[k] = sorted[k-1];
                        k--;
                    }
                    sorted[k] = tmp;
                }
                fprintf(f, "{\n");
                for (size_t j = 0; j < v->object.count; j++) {
                    fprintf(f, "%s", pad_inner);
                    print_string_escaped(f, sorted[j].key);
                    fprintf(f, ": ");
                    print_value(f, sorted[j].value, indent, depth + 1);
                    if (j + 1 < v->object.count) fputc(',', f);
                    fputc('\n', f);
                }
                fprintf(f, "%s}", pad);
                free(sorted);
            }
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    if (!buf) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    *out_len = rd;
    fclose(f);
    return buf;
}

