    size_t len_a, len_b;
    char *buf_a = read_file("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/config_a.json", &len_a);
    char *buf_b = read_file("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_vgwgt8n1/config_b.json", &len_b);

    parser pa = { buf_a, 0, len_a };
